def is_palindrome(s):
	count = 0
	length = len(s)
	symmetrical_ch_count = int(length/2)

	for i in range( 0 , symmetrical_ch_count ):
			if (s[i] == s[(length-1)-i]):
				count = count + 1
	if(count == symmetrical_ch_count):
		return True
	else:
		return False

