def get_first_duplicate(input_str):
    position = {}  # 用于记录字符第一次出现的位置

    for i, char in enumerate(input_str):
        if char in position:
            return char  # 当前字符已经出现过，直接返回
        else:
            position[char] = i  # 记录字符第一次出现的位置

    return ""  # 没有重复字符，返回空字符串


