position = {}

def get_first_duplicate(input_str):
    res = ''
    pos = int(len(input_str))
    for i in input_str:
        if i not in position:
            position[i] = input_str.index(i)
        else:
            if input_str.index(i)<pos:
                res = i
                pos = input_str.index(i)
    return res

