def add_matrix(input_list_1, input_list_2):
    m = 0
    n = 0
    for i in range(len(input_list_1)):
        for j in range(len(input_list_1[i])):

    for a in range(len(input_list_2)):
        for b in range(len(input_list_2[a])):

        input_list_1[i][j] = input_list_1[i][j] + input_list_1[a][b]

    return input_list_1           

