position = {}
def get_first_duplicate(input_str):
    pos = int(len(input_str))
    res = str()
    for i in input_str:
        if i not in position:
            position[i] = input_str.index(i) # index()函数为返回字符所在索引的位置
        else:
            if position[i] < pos:
                res = i
                pos = position[i]
    return res

