def get_first_duplicate(input_str):

    position = {}
    res = ''
    pos = -1

    for i in input_str:
        if i in position:
            if position[i] < pos:
                res = i
                pos = position[i]

        else:
            position[i] = -(len(input_str) + input_str.index(i))

    return res

